// Terceira expansão: cálculo separado da interpretação e fontes por instrumento.
import {s,y,n,ref,b,make,ordinal} from './expanded-scores.mjs';
const meta=f=>({...f,noPoints:true});
const pmc=(id,title)=>ref(title,`https://pmc.ncbi.nlm.nih.gov/articles/${id}/`);
const R={
 orbit:pmc('PMC4670965','O’Brien et al. · ORBIT original · 2015'),atria:pmc('PMC3175766','Fang et al. · ATRIA bleeding · 2011'),
 ra:pmc('PMC9521837','Estudo brasileiro REAL · fórmulas DAS28, CDAI e SDAI · 2022'),
 asdas:ref('ASAS · ASDAS oficial · fórmulas, cortes e piso de PCR','https://www.asas-group.org/instruments/asdas-calculator/'),
 renal:ref('NIDDK · CKD-EPI 2021 em adultos · creatinina','https://www.niddk.nih.gov/research-funding/research-programs/kidney-clinical-research-epidemiology/laboratory/glomerular-filtration-rate-equations/adults'),
 must:ref('BAPEN · Malnutrition Universal Screening Tool (MUST)','https://www.bapen.org.uk/pdfs/must/must-full.pdf'),
 conut:ref('Estudo clínico · critérios CONUT · Scientific Reports 2026','https://www.nature.com/articles/s41598-026-43288-z'),
 isar:pmc('PMC8909123','ISAR · adaptação transcultural brasileira · versão final 2022'),
 urticaria:pmc('PMC13466004','Diretriz internacional de urticária · atualização 2026'),
 salt:pmc('PMC11962811','II Consenso da Sociedade Brasileira de Dermatologia sobre alopecia areata · 2025'),
 pucai:ref('NICE NG130 · PUCAI · tabela 2','https://www.nice.org.uk/guidance/ng130/chapter/recommendations'),
 twist:ref('ACEP · TWIST · tabela de critérios e contexto clínico','https://www.acep.org/emultrasound/newsroom/september-2022/cases-that-count-whirlpool-sign-in-testicular-torsion'),
 aki:pmc('PMC4057151','KDIGO · definição e estadiamento de LRA · diretriz final 2012'),
 maddrey:ref('AASLD · função discriminante de Maddrey · fórmula modificada','https://www.aasld.org/liver-fellow-network/core-series/why-series/why-do-we-use-steroids-maddreys-discriminant-function')
};
const result=(total,label,action,audit,level='medium',breakdown=[])=>({total,label,action,audit,level,breakdown});
const activity='Interpretar com exame, evolução e avaliação especializada. A classificação não determina tratamento isoladamente.';
const bleeding='Revisar fatores modificáveis, interações e monitorização. Risco de sangramento não é motivo isolado para suspender ou negar anticoagulação.';
const continuous=o=>make({range:'Índice contínuo',resultScale:false,unit:'índice',...o});
export const clinicalScores=[
make({id:'orbit',name:'ORBIT',specialty:'Cardiologia',subtitle:'Risco hemorrágico na fibrilação atrial',max:7,scope:'Adultos com fibrilação atrial em anticoagulação oral; versão original de cinco fatores.',fields:[y('age','Idade ≥75 anos'),y('anemia','Anemia ou história de anemia',2,'Hb <13 g/dL em homens ou <12 em mulheres; ou Ht <40% / <36%, respectivamente; ou história de anemia.'),y('bleed','História de sangramento',2),y('renal','TFGe <60 mL/min/1,73 m²'),y('antiplatelet','Uso de antiplaquetário')],bands:[b(2,'Risco baixo','low',bleeding),b(3,'Risco intermediário','medium',bleeding),b(7,'Risco alto','high',bleeding)],limits:'Estimativa de risco em uma população; não é probabilidade individual nem comparação direta com HAS-BLED ou ATRIA.',sources:[R.orbit]}),
make({id:'atria-bleeding',name:'ATRIA · sangramento',specialty:'Cardiologia',subtitle:'Risco hemorrágico · versão para varfarina',max:10,scope:'Adultos com fibrilação atrial tratados com varfarina; não confundir com ATRIA de risco de AVC.',fields:[y('anemia','Hb <13 g/dL (homens) ou <12 g/dL (mulheres)',3),y('renal','TFGe <30 mL/min/1,73 m² ou diálise',3),y('age','Idade ≥75 anos',2),y('bleed','Hemorragia prévia'),y('htn','Hipertensão arterial')],bands:[b(3,'Risco baixo','low',bleeding),b(4,'Risco intermediário','medium',bleeding),b(10,'Risco alto','high',bleeding)],limits:'Derivado em usuários de varfarina; não presumir a mesma calibração para todos os anticoagulantes ou populações.',sources:[R.atria]}),
ordinal('killip','Killip–Kimball','Cardiologia',[[1,'Sem sinais clínicos de insuficiência cardíaca'],[2,'Estertores, terceira bulha ou sinais de insuficiência cardíaca sem edema pulmonar franco'],[3,'Edema agudo de pulmão franco'],[4,'Choque cardiogênico: hipotensão e hipoperfusão periférica']],'Classificação clínica na apresentação do infarto agudo do miocárdio. Registrar o momento da avaliação.',[ref('ESC · diretriz de insuficiência cardíaca · classificação Killip','https://academic.oup.com/eurheartj/article/37/27/2129/1748921')],'Não determina estratégia de reperfusão. Choque pode ocorrer sem congestão pulmonar; avaliar perfusão e causas alternativas.','classe'),
continuous({id:'ckdepi2021',name:'CKD-EPI 2021 · creatinina',specialty:'Nefrologia',subtitle:'TFG estimada · sem variável de raça',unit:'mL/min/1,73 m²',scope:'Adultos ≥18 anos, com creatinina padronizada e função renal em estado estável. Equação CKD-EPI 2021 baseada somente em creatinina.',fields:[n('age','Idade (anos)',18,120),meta(s('sex','Sexo empregado na equação original',[[0,'Masculino'],[1,'Feminino']])),n('cr','Creatinina (mg/dL)',.1,30,.01)],formula:'142 × min(Cr/κ,1)^α × max(Cr/κ,1)^−1,200 × 0,9938^idade × (1,012 se feminino). κ=0,7/0,9; α=−0,241/−0,302 (feminino/masculino).',compute:x=>{const k=x.sex?.7:.9,a=x.sex?-.241:-.302,v=142*Math.min(x.cr/k,1)**a*Math.max(x.cr/k,1)**-1.2*.9938**x.age*(x.sex?1.012:1);return result(v,'TFG estimada e indexada','Interpretar tendência, albuminúria e contexto. Considerar cistatina C ou medida de TFG quando a precisão influenciar decisões.',`142 × min(${x.cr}/${k},1)^${a} × max(${x.cr}/${k},1)^−1,2 × 0,9938^${x.age} × ${x.sex?1.012:1}`);},limits:'Não usar como medida confiável na lesão renal aguda ou creatinina rapidamente variável. Massa muscular e dieta interferem. Não é clearance de Cockcroft–Gault; não usar diretamente para qualquer ajuste de dose.',sources:[R.renal]}),
continuous({id:'cockcroft-gault',name:'Cockcroft–Gault',specialty:'Nefrologia',subtitle:'Clearance estimado de creatinina · não indexado',unit:'mL/min',scope:'Adultos com creatinina estável. Inserir o peso escolhido clinicamente para a aplicação pretendida, documentando se atual, ideal ou ajustado.',fields:[n('age','Idade (anos)',18,120),n('weight','Peso adotado (kg)',20,350,.1),n('cr','Creatinina (mg/dL)',.1,30,.01),meta(s('sex','Sexo empregado na equação original',[[0,'Masculino'],[1,'Feminino']]))],formula:'(140 − idade) × peso / (72 × creatinina); multiplicar por 0,85 no sexo feminino.',compute:x=>result((140-x.age)*x.weight/(72*x.cr)*(x.sex?.85:1),'Clearance estimado não indexado','Conferir o método exigido pela decisão clínica ou bula e a adequação do peso utilizado.',`(140 − ${x.age}) × ${x.weight} / (72 × ${x.cr}) × ${x.sex?.85:1}`),limits:'Não é TFGe indexada. Obesidade, edema, amputação e extremos de massa muscular exigem avaliação específica do peso e da estimativa. Não arredondar creatinina baixa para 1 automaticamente. Inadequado na LRA.',sources:[ref('National Kidney Foundation · KDOQI · equações de função renal','https://www.kidney.org/sites/default/files/2024-08/ckd_evaluation_classification_stratification.pdf')]}),
continuous({id:'schwartz2009',name:'Schwartz bedside · 2009',specialty:'Nefrologia',population:'Pediatria · 1–16 anos',subtitle:'TFG pediátrica estimada por altura e creatinina',unit:'mL/min/1,73 m²',scope:'Crianças de 1–16 anos; equação simplificada CKiD 2009 com creatinina padronizada por IDMS, em estado estável.',fields:[n('height','Altura (cm)',40,210,.1),n('cr','Creatinina (mg/dL)',.1,20,.01)],formula:'TFGe = 0,413 × altura em cm / creatinina em mg/dL.',compute:x=>result(.413*x.height/x.cr,'TFG pediátrica estimada','Avaliar trajetória e contexto nefrológico; comparar somente equações e métodos laboratoriais compatíveis.',`0,413 × ${x.height} / ${x.cr}`),limits:'Não é a equação CKiD U25, nem a Schwartz original com coeficientes por idade. Não extrapolar para neonatos ou LRA. Derivação em crianças com DRC; imprecisão em TFG alta e extremos corporais.',sources:[ref('NIDDK · protocolo CKiD · equação bedside de Schwartz','https://repository.niddk.nih.gov/public/study_document/CKiD_V7/Documents/CKiD_Study_Protocol_06-01-16_to_08-01-17_clean.pdf')]}),
make({id:'kdigo-aki',name:'KDIGO · lesão renal aguda',specialty:'Nefrologia',population:'Adultos e pediatria · critérios por contexto',subtitle:'Estadiamento · diretriz final 2012',max:3,unit:'estágio',resultScale:false,scope:'Aplicar no contexto de alteração renal aguda: aumento de Cr ≥0,3 mg/dL em 48 h, ≥1,5× basal em até 7 dias, ou oligúria <0,5 mL/kg/h por ≥6 h. Selecionar o pior critério em cada domínio.',fields:[meta(s('cr','Creatinina / terapia renal substitutiva',[[0,'Nenhum critério renal agudo listado'],[1,'Cr 1,5 a <2× basal ou aumento ≥0,3 mg/dL em 48 h'],[2,'Cr 2 a <3× basal'],[3,'Cr ≥3× basal; ou Cr ≥4 mg/dL em LRA; ou início de TRS; ou <18 anos com queda aguda da TFGe para <35 mL/min/1,73 m²']],'Critérios de estágio 3 exigem contexto agudo. Uma creatinina cronicamente ≥4 não basta.')),meta(s('urine','Diurese e duração',[[0,'Sem critério de oligúria listado'],[1,'<0,5 mL/kg/h por 6 a <12 h'],[2,'<0,5 mL/kg/h por ≥12 h, sem critério de estágio 3'],[3,'<0,3 mL/kg/h por ≥24 h ou anúria por ≥12 h']]))],formula:'Maior estágio entre creatinina/TRS e diurese; não somar domínios.',compute:x=>{const v=Math.max(x.cr,x.urine);return result(v,v?`KDIGO estágio ${v}`:'Sem critério selecionado de LRA','Investigar causas e acompanhar função renal e diurese. O estágio não é uma indicação automática de diálise.',`máximo(${x.cr}, ${x.urine})`,v>=2?'high':'medium',[{label:'Creatinina/TRS',points:x.cr},{label:'Diurese',points:x.urine}]);},limits:'Dados desconhecidos não equivalem a ausência. Não estimar creatinina basal arbitrariamente. Usada a diretriz final de 2012; o rascunho KDIGO 2026 não é tratado como diretriz final.',sources:[R.aki,ref('KDIGO 2012 · tabela 2, página 19 · unidade e critério pediátrico','https://kdigo.org/wp-content/uploads/2016/10/KDIGO-2012-AKI-Guideline-English.pdf'),ref('KDIGO · estado da atualização AKI/AKD','https://kdigo.org/guidelines/acute-kidney-injury/')]}),
continuous({id:'maddrey',name:'Maddrey · mDF',specialty:'Hepatologia',subtitle:'Função discriminante modificada',scope:'Adultos com hepatite associada ao álcool clinicamente estabelecida. Utilizar tempo de protrombina do paciente e controle do próprio laboratório, em segundos.',fields:[n('pt','TP do paciente (segundos)',5,150,.1),n('control','TP controle do laboratório (segundos)',5,40,.1),n('bilirubin','Bilirrubina total (mg/dL)',0,100,.1)],formula:'mDF = 4,6 × (TP paciente − TP controle) + bilirrubina total.',compute:x=>{const v=4.6*(x.pt-x.control)+x.bilirubin;return result(v,v>=32?'mDF ≥32 · faixa de gravidade':'mDF <32','Integrar ao diagnóstico, encefalopatia e avaliação de gravidade. O resultado não prescreve corticosteroide.',`4,6 × (${x.pt} − ${x.control}) + ${x.bilirubin}`,v>=32?'high':'medium');},limits:'Não substituir TP por INR. Controle laboratorial influencia a pontuação. Infecção, hemorragia e outras contraindicações precisam de avaliação própria antes de qualquer terapia.',sources:[R.maddrey]}),
make({id:'must',name:'MUST',specialty:'Nutrição',subtitle:'Triagem de risco nutricional em adultos',max:6,scope:'Adultos; versão BAPEN de três componentes. Dados antropométricos e perda involuntária de peso conhecidos.',fields:[s('bmi','IMC (kg/m²)',[[0,'>20'],[1,'18,5 a 20'],[2,'<18,5']]),s('loss','Perda de peso involuntária nos últimos 3–6 meses',[[0,'<5%'],[1,'5–10%'],[2,'>10%']]),y('acute','Doença aguda com ausência de aporte nutricional por >5 dias, ocorrida ou provável',2)],bands:[b(0,'Risco baixo','low','Documentar e repetir a triagem conforme contexto.'),b(1,'Risco médio','medium','Avaliar ingestão e evolução nutricional.'),b(6,'Risco alto','high','Encaminhar para avaliação e plano nutricional individualizado.')],limits:'Triagem não equivale a diagnóstico de desnutrição. Não utilizar valores presumidos em edema, gestação ou antropometria inviável; consultar orientações BAPEN. Critérios e atribuição: BAPEN/MAG, MUST.',sources:[R.must]}),
make({id:'conut',name:'CONUT',specialty:'Nutrição',subtitle:'Índice laboratorial de risco nutricional',max:12,scope:'Adultos; índice baseado em albumina, linfócitos totais e colesterol total, colhidos no contexto clínico avaliado.',fields:[s('albumin','Albumina (g/dL)',[[0,'≥3,5'],[2,'3 a <3,5'],[4,'2,5 a <3'],[6,'<2,5']]),s('lymph','Linfócitos totais (/mm³)',[[0,'≥1.600'],[1,'1.200–1.599'],[2,'800–1.199'],[3,'<800']]),s('chol','Colesterol total (mg/dL)',[[0,'≥180'],[1,'140–179'],[2,'100–139'],[3,'<100']])],bands:[b(1,'Faixa normal do índice','low',activity),b(4,'Alteração leve','medium',activity),b(8,'Alteração moderada','medium',activity),b(12,'Alteração grave','high',activity)],limits:'Não diagnostica desnutrição isoladamente. Inflamação, doença hepática, perdas proteicas, imunossupressão e tratamento hipolipemiante podem alterar os componentes.',sources:[R.conut]}),
make({id:'isar-br',name:'ISAR · adaptação brasileira',specialty:'Geriatria',population:'Pessoas idosas',subtitle:'Rastreio de risco · versão brasileira 2022',max:6,scope:'Pessoas idosas atendidas em emergência. Tradução/adaptação brasileira de seis perguntas, respondidas com o paciente e/ou informante confiável.',fields:[y('help','Antes do problema atual, precisava regularmente de ajuda de outra pessoa?'),y('more','Nas últimas 24 h, precisou de mais ajuda que o habitual?'),y('hospital','Internou por uma noite ou mais nos últimos 6 meses?'),y('vision','Tem problema importante de visão não corrigido por óculos?'),y('memory','Tem problema importante de memória?'),y('meds','Usa cinco ou mais medicamentos diferentes diariamente?')],action:'Maior número de respostas positivas indica maior carga de fatores de vulnerabilidade. Realizar avaliação geriátrica e do suporte disponível conforme contexto.',limits:'Versão final brasileira 2022 usa ≥5 medicamentos. Não misturar com versões originais de 3 ou 6. O estudo citado é de adaptação transcultural; não confere validação prognóstica brasileira nem um limiar universal de alta.',sources:[R.isar]}),
make({id:'uas7',name:'UAS7',specialty:'Dermatologia',subtitle:'Atividade de urticária · diário de 7 dias',max:42,scope:'Urticária espontânea com urticas e prurido. Informar cada um dos sete dias consecutivos, idealmente a partir do diário prospectivo do paciente.',fields:Array.from({length:7},(_,i)=>[s(`w${i}`,'Urticas em 24 h',[[0,'Nenhuma'],[1,'Menos de 20'],[2,'20–50'],[3,'Mais de 50 ou grandes áreas confluentes']],'',`Dia ${i+1}`),s(`p${i}`,'Prurido em 24 h',[[0,'Ausente'],[1,'Leve, sem incômodo relevante'],[2,'Incômodo, mas sem interferir na atividade ou sono'],[3,'Interfere na atividade ou no sono']],'',`Dia ${i+1}`)]).flat(),action:'Comparar atividade ao longo do tempo. Zero representa ausência de urticas e prurido nos sete dias registrados.',limits:'Não preencher dia desconhecido com zero. Não mede angioedema, anafilaxia ou apenas controle subjetivo; não é o UCT. Escore alto não determina por si só uma medicação.',sources:[R.urticaria]}),
continuous({id:'salt',name:'SALT',specialty:'Dermatologia',subtitle:'Extensão da perda capilar no couro cabeludo',range:'0–100%',unit:'%',max:100,scope:'Alopecia areata; estimar separadamente o percentual de perda de cabelo terminal em cada região do couro cabeludo.',fields:[n('top','Perda na região superior (%)',0,100,.1),n('back','Perda posterior (%)',0,100,.1),n('right','Perda lateral direita (%)',0,100,.1),n('left','Perda lateral esquerda (%)',0,100,.1)],formula:'0,40 × superior + 0,24 × posterior + 0,18 × direita + 0,18 × esquerda.',compute:x=>result(.4*x.top+.24*x.back+.18*x.right+.18*x.left,'Percentual ponderado de perda capilar',activity,`0,40 × ${x.top} + 0,24 × ${x.back} + 0,18 × ${x.right} + 0,18 × ${x.left}`),limits:'Não inclui sobrancelhas, cílios, pelos corporais, unhas ou impacto psicossocial. Utilizar a divisão anatômica padronizada e comparar fotografias/avaliações consistentes.',sources:[R.salt]}),
make({id:'pucai',name:'PUCAI',specialty:'Gastroenterologia',population:'Crianças e adolescentes',subtitle:'Atividade de retocolite ulcerativa pediátrica',max:85,scope:'Crianças e adolescentes com retocolite ulcerativa estabelecida. Considerar a média diária dos sintomas dos últimos 2 dias; se o quadro estiver mudando rapidamente, considerar as últimas 24 horas. Em avaliação associada à colonoscopia, usar os 2 dias anteriores ao início do preparo intestinal.',fields:[s('pain','Dor abdominal',[[0,'Ausente'],[5,'Pode ser ignorada'],[10,'Não pode ser ignorada']]),s('blood','Sangramento retal',[[0,'Ausente'],[10,'Pequena quantidade em menos da metade das evacuações'],[20,'Pequena quantidade na maioria das evacuações'],[30,'Grande quantidade: mais de 50% do conteúdo fecal']]),s('form','Consistência predominante das fezes',[[0,'Formadas'],[5,'Parcialmente formadas'],[10,'Completamente não formadas']]),s('stools','Evacuações em 24 h',[[0,'0–2'],[5,'3–5'],[10,'6–8'],[15,'Mais de 8']]),y('night','Evacuação noturna que cause despertar',10),s('activity','Nível de atividade',[[0,'Sem limitação'],[5,'Limitação ocasional'],[10,'Restrição importante']])],bands:[b(9,'Remissão clínica pelo PUCAI','low',activity),b(34,'Atividade leve','medium',activity),b(64,'Atividade moderada','medium',activity),b(85,'Atividade grave','high','Avaliação especializada urgente de colite grave e complicações.')],limits:'Não é índice de Crohn nem prova de remissão endoscópica. Sangramento, infecção e outras causas precisam de investigação própria.',sources:[R.pucai,ref('GEDIIB · consenso pediátrico 2022 · PUCAI: janela de avaliação · p. 87','https://gediib.org.br/wp-content/uploads/2023/03/consenso-de-pediatria-2023-GEDIIB.pdf')]}),
make({id:'twist',name:'TWIST',specialty:'Urologia',population:'Pediatria · meninos com escroto agudo',subtitle:'Suspeita de torção testicular',max:7,scope:'Meninos com dor/alteração escrotal aguda, submetidos a exame físico adequado. Não extrapolar automaticamente para todas as faixas etárias.',fields:[y('swelling','Aumento de volume testicular',2),y('hard','Testículo endurecido',2),y('reflex','Reflexo cremastérico ausente'),y('nausea','Náusea ou vômito'),y('high','Testículo elevado')],action:'Maior escore aumenta a suspeita. Suspeita clínica de torção exige avaliação urológica urgente; não aguardar o cálculo ou imagem para acionar a equipe.',limits:'Escore baixo não exclui torção em apresentação atípica, parcial ou intermitente. Desempenho depende do examinador e da população. Na validação de Sheth 2016, a precisão foi maior nos estágios puberais Tanner 3–5; isso não autoriza excluir torção em pré-púberes nem dispensar investigação. Tanner não soma pontos nesta ficha. As faixas de risco de estudos diferentes não são intercambiáveis; nenhum total autoriza alta automática.',sources:[R.twist,ref('Barbosa et al. · derivação TWIST 2013 · registro primário com errata vinculada','https://pubmed.ncbi.nlm.nih.gov/23103800/'),ref('Sheth et al. · validação 2016; cortes próprios, não importados','https://pubmed.ncbi.nlm.nih.gov/26835833/'),ref('Johns Hopkins · escroto agudo; conteúdo clínico dez/2022, atualização administrativa maio/2026','https://www.hopkinsmedicine.org/-/media/files/allchildrens/clinical-pathways/acute-scrotal-pain-clinical-pathway--5_11_26.pdf')]})
];
// Índices de atividade reumatológica: unidades não intercambiáveis.
for(const kind of ['esr','crp']) clinicalScores.push(continuous({id:`das28-${kind}`,name:`DAS28 · ${kind==='esr'?'VHS':'PCR'}`,specialty:'Reumatologia',subtitle:'Atividade de artrite reumatoide · quatro variáveis',scope:'Adultos com artrite reumatoide. Contagem padronizada de 28 articulações; avaliação global do paciente em escala de 0 a 100 mm.',fields:[n('tender','Articulações dolorosas (28)',0,28),n('swollen','Articulações edemaciadas (28)',0,28),n('global','Avaliação global do paciente (0–100 mm)',0,100,.1),n('lab',kind==='esr'?'VHS (mm/h)':'PCR (mg/L)',kind==='esr'?1:0,kind==='esr'?200:500,.1)],formula:kind==='esr'?'0,56√dolorosas + 0,28√edemaciadas + 0,70 ln(VHS) + 0,014 global.':'0,56√dolorosas + 0,28√edemaciadas + 0,36 ln(PCR + 1) + 0,014 global + 0,96.',compute:x=>{const v=.56*Math.sqrt(x.tender)+.28*Math.sqrt(x.swollen)+.014*x.global+(kind==='esr'?.7*Math.log(x.lab):.36*Math.log(x.lab+1)+.96);return result(v,v<2.6?'Remissão pelo índice':v<=3.2?'Atividade baixa':v<=5.1?'Atividade moderada':'Atividade alta',activity,`D28=${x.tender}; E28=${x.swollen}; global=${x.global}; ${kind.toUpperCase()}=${x.lab}; fórmula ${kind==='esr'?'VHS':'PCR'}`,v>5.1?'high':'medium');},limits:'As fórmulas VHS e PCR não são intercambiáveis. Não inclui tornozelos/pés. Remissão pelo índice não garante ausência de sinovite. Classificação usa o valor antes do arredondamento; ln é logaritmo natural.',sources:[R.ra]}));
for(const kind of ['cdai','sdai']) clinicalScores.push(continuous({id:kind,name:kind.toUpperCase()+' · artrite reumatoide',specialty:'Reumatologia',subtitle:'Índice simplificado de atividade',scope:'Adultos com artrite reumatoide estabelecida; contagem de 28 articulações e avaliações globais de paciente e examinador.',fields:[n('tender','Articulações dolorosas (28)',0,28),n('swollen','Articulações edemaciadas (28)',0,28),n('patient','Avaliação global do paciente (0–10)',0,10,.1),n('doctor','Avaliação global do examinador (0–10)',0,10,.1),...(kind==='sdai'?[n('crp','PCR (mg/dL)',0,100,.01)]:[])],formula:'Dolorosas + edemaciadas + global do paciente + global do examinador'+(kind==='sdai'?' + PCR em mg/dL.':'.'),compute:x=>{const v=x.tender+x.swollen+x.patient+x.doctor+(x.crp||0),cuts=kind==='cdai'?[2.8,10,22]:[3.3,11,26];return result(v,v<=cuts[0]?'Remissão pelo índice':v<=cuts[1]?'Atividade baixa':v<=cuts[2]?'Atividade moderada':'Atividade alta',activity,`${x.tender} + ${x.swollen} + ${x.patient} + ${x.doctor}${kind==='sdai'?` + ${x.crp}`:''}`,v>cuts[2]?'high':'medium');},limits:'CDAI aqui é o Clinical Disease Activity Index de artrite reumatoide, não o índice de Crohn. Globais são 0–10, não 0–100. SDAI exige PCR em mg/dL; dividir mg/L por 10 antes de informar.',sources:[R.ra]}));
for(const kind of ['crp','esr']) clinicalScores.push(continuous({id:`asdas-${kind}`,name:`ASDAS · ${kind==='crp'?'PCR':'VHS'}`,specialty:'Reumatologia',subtitle:'Atividade de espondiloartrite axial',scope:'Adultos com espondiloartrite axial estabelecida. Quatro avaliações de 0 a 10; rigidez é a escala padronizada de duração do BASDAI (0: ausente; 10: ≥2 h), não minutos livres.',fields:[n('back','Dor lombar total (0–10)',0,10,.1),n('global','Avaliação global do paciente (0–10)',0,10,.1),n('peripheral','Dor/edema periférico (0–10)',0,10,.1),n('stiff','Duração da rigidez matinal · escala BASDAI (0–10)',0,10,.1),n('lab',kind==='crp'?'PCR (mg/L)':'VHS (mm/h)',0,kind==='crp'?500:200,.1)],formula:kind==='crp'?'0,121 dor lombar + 0,110 global + 0,073 periférico + 0,058 rigidez + 0,579 ln(PCR + 1). PCR <2 mg/L é fixada em 2.':'0,079 dor lombar + 0,113 global + 0,086 periférico + 0,069 rigidez + 0,293√VHS.',compute:x=>{const v=kind==='crp'?.121*x.back+.110*x.global+.073*x.peripheral+.058*x.stiff+.579*Math.log(Math.max(x.lab,2)+1):.079*x.back+.113*x.global+.086*x.peripheral+.069*x.stiff+.293*Math.sqrt(x.lab);return result(v,v<1.3?'Doença inativa':v<2.1?'Atividade baixa':v<=3.5?'Atividade alta':'Atividade muito alta',activity,`Lombar=${x.back}; global=${x.global}; periférico=${x.peripheral}; rigidez=${x.stiff}; ${kind==='crp'?`PCR usada=${Math.max(x.lab,2)} mg/L (piso 2)`:`VHS=${x.lab}`}`,v>3.5?'high':'medium');},limits:'Não diagnostica espondiloartrite. PCR é a versão preferencial ASAS; VHS é alternativa, com fórmula distinta. Comparar a mesma versão em série. Não confundir escala de duração de rigidez com intensidade.',sources:[R.asdas,ref('ASAS · handbook · fórmulas ASDAS','https://www.asas-group.org/wp-content/uploads/2020/07/ASAS-handbook.pdf')]}));
const nt=['NT','Não testável / basal desconhecido'];
const sumWithNT=(x,action,scoreId)=>{if(Object.values(x).includes('NT'))return result(null,'Total não calculável','Documentar o componente não testável; não imputar valor normal.', 'Componente NT');const entries=Object.entries(x);return result(entries.reduce((a,[,v])=>a+v,0),'Pontuação de gravidade',action,entries.map(([,v])=>v).join(' + '),'medium',entries.map(([id,points])=>({label:clinicalScores.find(s=>s.id===scoreId)?.fields.find(f=>f.id===id)?.label||id,points})));};
clinicalScores.push(make({id:'saps2',name:'SAPS II · IGS II',specialty:'Terapia intensiva',subtitle:'Gravidade nas primeiras 24 horas de UTI',max:163,scope:'Adultos ≥18 anos em UTI; pior valor de cada variável nas primeiras 24 h. Não aplicar às populações excluídas da derivação: queimados, cirurgia cardíaca e unidades coronarianas.',fields:[s('admission','Tipo de admissão',[[0,'Cirurgia programada'],[6,'Clínica'],[8,'Cirurgia urgente']],'Cirúrgico: operação na semana antes/depois da UTI; programada se planejada ≥24 h antes.'),s('disease','Doença de base · maior categoria',[[0,'Nenhuma das listadas'],[9,'Câncer metastático'],[10,'Neoplasia hematológica'],[17,'AIDS com complicações clínicas']]),s('gcs','Menor Glasgow (antes da sedação)',[[0,'14–15'],[5,'11–13'],[7,'9–10'],[13,'6–8'],[26,'3–5'],nt]),s('age','Idade (anos)',[[0,'18–39'],[7,'40–59'],[12,'60–69'],[15,'70–74'],[16,'75–79'],[18,'≥80']]),s('sbp','Pior PAS (mmHg)',[[0,'100 a <200'],[2,'≥200'],[5,'70 a <100'],[13,'<70']]),s('hr','Pior FC (bpm)',[[0,'70 a <120'],[2,'40 a <70'],[4,'120 a <160'],[7,'≥160'],[11,'<40']]),s('temp','Maior temperatura central (°C)',[[0,'<39'],[3,'≥39']]),s('oxygen','Oxigenação · VM ou CPAP',[[0,'Sem VM e sem CPAP'],[6,'Com VM/CPAP e P/F ≥200'],[9,'Com VM/CPAP e P/F 100 a <200'],[11,'Com VM/CPAP e P/F <100']],'P/F em mmHg: PaO₂ / FiO₂ em fração. Usar o menor quociente.'),s('urine','Diurese (L/24 h)',[[0,'≥1'],[4,'0,5 a <1'],[11,'<0,5']],'Se período <24 h, extrapolar volume para 24 h conforme método original.'),s('urea','Maior ureia (mg/dL)',[[0,'<60'],[6,'60 a <180'],[10,'≥180']],'Ureia, NÃO BUN. Equivalentes aproximados: <10; 10 a <30; ≥30 mmol/L.'),s('wbc','Pior leucograma (mil/mm³)',[[0,'1 a <20'],[3,'≥20'],[12,'<1']]),s('k','Pior potássio (mEq/L)',[[0,'3 a <5'],[3,'<3 ou ≥5']]),s('na','Pior sódio (mEq/L)',[[0,'125 a <145'],[1,'≥145'],[5,'<125']]),s('hco','Menor bicarbonato (mEq/L)',[[0,'≥20'],[3,'15 a <20'],[6,'<15']]),s('bili','Maior bilirrubina (mg/dL)',[[0,'<4'],[4,'4 a <6'],[9,'≥6']],'Na fonte SFAR, medir se ictérico; se avaliação necessária estiver ausente, não presumir normal.')],compute:x=>sumWithNT(x,'Descrever componentes e gravidade. Não converte automaticamente o escore em mortalidade individual.','saps2'),limits:'Modelo de 1993; calibração de mortalidade depende de época e população. Não define admissão, alta ou limitação terapêutica. Para dado faltante necessário, não calcular; Glasgow NT bloqueia a soma.',sources:[ref('SFAR · SAPS II · Le Gall et al. · tabela e definições','https://sfar.org/scores/igs2.php')]}));
clinicalScores.push(make({id:'apache2',name:'APACHE II',specialty:'Terapia intensiva',subtitle:'Fisiologia aguda, idade e saúde crônica',max:71,scope:'Adultos em UTI. Pior valor de cada variável nas primeiras 24 h. Selecionar somente uma modalidade para oxigenação e uma para equilíbrio ácido-base.',fields:[s('temp','Temperatura central (°C)',[[0,'36 a <38,5'],[1,'34 a <36 ou 38,5 a <39'],[2,'32 a <34'],[3,'30 a <32 ou 39 a <41'],[4,'<30 ou ≥41']]),s('map','PAM (mmHg)',[[0,'70 a <110'],[2,'50 a <70 ou 110 a <130'],[3,'130 a <160'],[4,'<50 ou ≥160']]),s('hr','FC (bpm)',[[0,'70–109'],[2,'55–69 ou 110–139'],[3,'40–54 ou 140–179'],[4,'<40 ou ≥180']]),s('rr','FR (irpm)',[[0,'12–24'],[1,'10–11 ou 25–34'],[2,'6–9'],[3,'35–49'],[4,'≤5 ou ≥50']]),s('oxygen','Oxigenação · modalidade conforme FiO₂',[[0,'FiO₂ <0,50: PaO₂ >70; OU FiO₂ ≥0,50: gradiente A–a <200'],[1,'FiO₂ <0,50: PaO₂ >60 a 70'],[2,'FiO₂ ≥0,50: gradiente A–a 200 a <350'],[3,'FiO₂ <0,50: PaO₂ 55–60; OU FiO₂ ≥0,50: gradiente A–a 350 a <500'],[4,'FiO₂ <0,50: PaO₂ <55; OU FiO₂ ≥0,50: gradiente A–a ≥500']],'Pressões em mmHg. Não inserir P/F no lugar do gradiente alvéolo-arterial.'),s('acid','pH arterial; HCO₃ somente se gasometria indisponível',[[0,'pH 7,33 a <7,50; OU HCO₃ 22 a <32'],[1,'pH 7,50 a <7,60; OU HCO₃ 32 a <41'],[2,'pH 7,25 a <7,33; OU HCO₃ 18 a <22'],[3,'pH 7,15 a <7,25 ou 7,60 a <7,70; OU HCO₃ 15 a <18 ou 41 a <52'],[4,'pH <7,15 ou ≥7,70; OU HCO₃ <15 ou ≥52']],'HCO₃ em mmol/L. Não somar pH e bicarbonato.'),s('na','Sódio (mmol/L)',[[0,'130 a <150'],[1,'150 a <155'],[2,'120 a <130 ou 155 a <160'],[3,'>110 a <120 ou 160 a <180'],[4,'≤110 ou ≥180']]),s('k','Potássio (mmol/L)',[[0,'3,5 a <5,5'],[1,'3 a <3,5 ou 5,5 a <6'],[2,'2,5 a <3'],[3,'6 a <7'],[4,'<2,5 ou ≥7']]),s('creat','Creatinina (mg/dL) · pontos antes de eventual duplicação',[[0,'0,6 a <1,5'],[2,'<0,6 ou 1,5 a <2'],[3,'2 a <3,5'],[4,'≥3,5']]),meta(y('acute','Insuficiência renal aguda (duplica apenas creatinina)')),s('hct','Hematócrito (%)',[[0,'30 a <46'],[1,'46 a <50'],[2,'20 a <30 ou 50 a <60'],[4,'<20 ou ≥60']]),s('wbc','Leucócitos (mil/mm³)',[[0,'3 a <15'],[1,'15 a <20'],[2,'1 a <3 ou 20 a <40'],[4,'<1 ou ≥40']]),meta(s('gcs','Glasgow testável antes da sedação',[...Array.from({length:13},(_,i)=>[15-i,String(15-i)]),nt])),s('age','Idade (anos)',[[0,'18–44'],[2,'45–54'],[3,'55–64'],[5,'65–74'],[6,'≥75']]),s('chronic','Insuficiência orgânica crônica grave / imunossupressão',[[0,'Ausentes'],[2,'Presentes e cirurgia eletiva'],[5,'Presentes e paciente clínico ou cirurgia urgente']],'Preexistentes: cirrose com hipertensão portal/descompensação; limitação cardíaca NYHA IV; doença respiratória com grave limitação/hipoxemia crônica; diálise crônica; ou imunossupressão conforme definição da fonte.')],formula:'Soma fisiológica + (15 − Glasgow) + idade + saúde crônica. Duplicar somente os pontos de creatinina na insuficiência renal aguda.',compute:x=>{if(x.gcs==='NT')return sumWithNT(x,'');const parts={...x,creat:x.creat*(x.acute?2:1),gcs:15-x.gcs};delete parts.acute;return sumWithNT(parts,'Comparar gravidade e componentes no contexto da UTI. Não é previsão individual de desfecho.','apache2');},limits:'Não soma pH com bicarbonato nem PaO₂ com gradiente A–a. A função renal aguda duplica a pontuação renal, não o total. Não estima mortalidade sem modelo diagnóstico e validação local. Ausência de dado não é normalidade.',sources:[ref('SFAR · APACHE II · tabela, modalidades e definições','https://sfar.org/scores/apache2.php')]}));
clinicalScores.push(make({id:'mnutric',name:'mNUTRIC',specialty:'Nutrição',subtitle:'Risco nutricional no paciente crítico · sem IL-6',max:9,scope:'Adultos em UTI; APACHE II e SOFA original calculados corretamente no período correspondente. Versão modificada que exclui IL-6.',fields:[s('age','Idade (anos)',[[0,'<50'],[1,'50–74'],[2,'≥75']]),s('apache','APACHE II',[[0,'<15'],[1,'15–19'],[2,'20–27'],[3,'≥28']]),s('sofa','SOFA original',[[0,'<6'],[1,'6–9'],[2,'≥10']]),y('comorbid','Duas ou mais comorbidades'),y('days','≥1 dia entre admissão hospitalar e admissão na UTI')],bands:[b(4,'Risco nutricional baixo pelo mNUTRIC','low',activity),b(9,'Risco nutricional alto pelo mNUTRIC','high','Avaliação nutricional individualizada e acompanhamento da tolerância e evolução.')],limits:'Não é diagnóstico de desnutrição nem prescrição de metas calóricas. Não substituir SOFA original por SOFA-2. Esta implementação adota APACHE II ≥28 na categoria máxima, conforme tabela da validação citada; há reproduções com limites diferentes.',sources:[pmc('PMC5842932','Validação do mNUTRIC · componentes e limiar ≥5'),pmc('PMC7400844','Validação NUTRIC/mNUTRIC · tabela com APACHE II 20–27 e ≥28 · 2020'),pmc('PMC9249235','Estudo de NUTRIC · faixas APACHE II explicitadas · 2022')]}));
for(const kind of ['gap','mgap']) clinicalScores.push(make({id:kind,name:kind.toUpperCase()+' · trauma',specialty:'Trauma',subtitle:kind==='gap'?'Glasgow, idade e pressão sistólica':'Mecanismo, Glasgow, idade e pressão sistólica',max:kind==='gap'?24:29,range:kind==='gap'?'3–24':'3–29',scope:'Adultos traumatizados, com parâmetros da avaliação inicial. Não confundir com índices GAP de doença pulmonar.',fields:[s('gcs','Glasgow',[...Array.from({length:13},(_,i)=>[15-i,String(15-i)]),nt]),s('age','Idade',[[kind==='gap'?3:5,'<60 anos'],[0,'≥60 anos']]),s('sbp','PAS (mmHg)',[[kind==='gap'?6:5,'>120'],[kind==='gap'?4:3,'60–120'],[0,'<60']]),...(kind==='mgap'?[s('mechanism','Mecanismo',[[4,'Contuso'],[0,'Penetrante']])]:[])],compute:x=>{const r=sumWithNT(x,'Integrar à avaliação primária e às lesões. Não substitui controle de hemorragia, suporte ou critérios locais de triagem.',kind);if(r.total!==null){const low=kind==='gap'?19:23,moderate=kind==='gap'?11:18;r.label=r.total>=low?'Faixa de risco baixo':r.total>=moderate?'Faixa de risco intermediário':'Faixa de risco alto';r.level=r.total>=low?'low':r.total>=moderate?'medium':'high';}return r;},limits:'Pontuação MENOR indica maior gravidade. NT no Glasgow impede cálculo; sedação/intubação não autorizam estimar uma resposta verbal. Não usar para prognóstico individual definitivo.',sources:[pmc('PMC3387633','Kondo et al. · GAP original · 2011'),pmc('PMC13141060','Protocolo prospectivo de avaliação de GAP/MGAP · tabela 1 · 2026')]}));
// Regras de decisão retornam status; o código numérico interno não é um novo escore.
const ruleResult=(positive,label,action,audit)=>({...result(positive?1:0,label,action,audit,positive?'high':'medium'),displayValue:positive?'Positiva':'Negativa'});
const rule=o=>make({range:'Regra clínica',resultScale:false,unit:'regra',max:1,...o,fields:o.fields.map(meta)});
clinicalScores.push(rule({id:'nexus-cspine',name:'NEXUS · coluna cervical',specialty:'Trauma',subtitle:'Regra de baixo risco após trauma contuso',scope:'Adultos com trauma contuso e suspeita de lesão cervical. Exame confiável e documentação de todos os critérios; não usar em trauma penetrante.',fields:[y('midline','Dor à palpação da linha média cervical posterior'),y('deficit','Déficit neurológico focal'),y('alert','Alerta/consciência alterados'),y('intox','Evidência de intoxicação'),y('distract','Lesão dolorosa que prejudique a atenção ao exame cervical')],formula:'A presença de qualquer um dos cinco achados impede liberação cervical pela regra NEXUS.',compute:x=>{const count=Object.values(x).reduce((a,b)=>a+b,0);return ruleResult(count>0,count?'Não preenche baixo risco NEXUS':'Todos os cinco critérios de baixo risco presentes','Integrar à avaliação de coluna e protocolo de imagem. Resultado negativo não supera exame duvidoso ou forte suspeita clínica.',`${count} achado(s) de risco; qualquer achado torna a regra positiva`);},limits:'Desempenho e aplicabilidade exigem cautela em idosos. Não autoriza testar mobilidade passiva forçada. Esta implementação não estende automaticamente a validação a crianças.',sources:[ref('ACEP · avaliação e liberação cervical · 2025','https://www.acep.org/sportsmedicine/newsroom/newsroom-articles/aug2025/clearing-the-c-collar-in-the-emergency-department-a-practical-guide')]}));
clinicalScores.push(rule({id:'ottawa-knee',name:'Ottawa · joelho',specialty:'Ortopedia',specialties:['Ortopedia','Pediatria'],population:'Adultos; pediatria >5–16 anos no contexto descrito',subtitle:'Critérios de radiografia após trauma agudo',scope:'Adultos com trauma agudo isolado de joelho e exame confiável. Extensão pediátrica local: >5 até 16 anos, trauma nos últimos 7 dias, suspeita clínica de lesão óssea e exame confiável. Esse recorte não é idade universal de validação; não aplicar a sintomas atraumáticos. A faixa etária e a elegibilidade são confirmadas clinicamente; o campo idade ≥55 anos não verifica a idade pediátrica.',fields:[y('age','Idade ≥55 anos'),y('patella','Dor óssea isolada na patela, sem dor em outro osso do joelho'),y('fibula','Dor na cabeça da fíbula'),y('flex','Incapaz de flexionar o joelho até 90°'),y('walk','Incapaz de apoiar por quatro passos imediatamente após trauma E na avaliação')],formula:'Qualquer um dos cinco critérios torna a regra positiva para radiografia.',compute:x=>{const c=Object.values(x).reduce((a,b)=>a+b,0);return ruleResult(c>0,c?'Critério de radiografia presente':'Sem critério de radiografia pela regra','Considerar radiografia se positiva; reavaliar persistência de dor ou exame incompatível mesmo quando negativa.',`${c} critério(s) presente(s)`);},limits:'Quatro passos são duas transferências de peso em cada membro, mesmo mancando. No estudo pediátrico, excluídos lesão isolada de pele, fratura já diagnosticada, retorno pelo mesmo trauma, consciência alterada, lesões distratoras múltiplas, doença óssea metabólica ou distúrbio sensitivo. Regra negativa não elimina toda fratura, lesão fisária ou lesão ligamentar/meniscal, nem autoriza alta. Persistência de dor, incapacidade funcional ou suspeita clínica exigem reavaliação. Desempenho variou: estudo de 2001 perdeu uma fratura tibial em criança de 8 anos; não prometer sensibilidade de 100% individual. Manter exclusões adultas do protocolo, inclusive gestação e trauma múltiplo.',sources:[ref('Bulloch et al. · validação pediátrica multicêntrica 2003','https://pubmed.ncbi.nlm.nih.gov/12827123/'),ref('Vijayasankar et al. · meta-análise pediátrica 2009','https://pubmed.ncbi.nlm.nih.gov/19307383/'),ref('Khine et al. · validação pediátrica 2001 · falso negativo relatado','https://pubmed.ncbi.nlm.nih.gov/11753181/'),ref('NSW Health · Ottawa Knee Rules em adultos','https://aci.health.nsw.gov.au/ecat/appendices/ottawa-knee'),pmc('PMC7476189','Validação de Ottawa Knee Rule em adultos · 2020')]}));
clinicalScores.push(rule({id:'ottawa-ankle',name:'Ottawa · tornozelo e pé',specialty:'Ortopedia',specialties:['Ortopedia','Pediatria'],population:'Adultos e pediatria >5 anos · exame confiável e marcha prévia normal',subtitle:'Duas regiões anatômicas, uma regra integrada',scope:'Adultos com trauma agudo de tornozelo/médiopé e exame confiável. Perfil pediátrico conservador deste site: maiores de 5 anos, comunicação confiável, marcha normal independente antes da lesão e avaliação inicial de trauma fechado há menos de 48 horas. Avaliar separadamente a região maleolar e o médiopé.',fields:[y('ankle','Dor na zona maleolar'),y('lateral','Dor óssea na borda posterior dos 6 cm distais ou ponta do maléolo lateral'),y('medial','Dor óssea na borda posterior dos 6 cm distais ou ponta do maléolo medial'),y('foot','Dor na zona do médiopé'),y('fifth','Dor óssea na base do quinto metatarso'),y('navicular','Dor óssea no navicular'),y('walk','Incapaz de apoiar por quatro passos imediatamente após trauma E na avaliação')],formula:'Tornozelo: dor maleolar E (dor óssea maleolar OU incapacidade de marcha). Pé: dor no médiopé E (dor no navicular/5º metatarso OU incapacidade de marcha).',compute:x=>{const ankle=x.ankle&&(x.lateral||x.medial||x.walk),foot=x.foot&&(x.fifth||x.navicular||x.walk);return ruleResult(!!(ankle||foot),ankle&&foot?'Critérios para tornozelo e pé':ankle?'Critério para tornozelo':foot?'Critério para pé':'Sem critério nas duas regiões','Correlacionar com exame e selecionar a região adequada para imagem. Dor persistente e lesões fora das zonas da regra requerem avaliação própria.',`Tornozelo: ${ankle?'positivo':'negativo'}; pé: ${foot?'positivo':'negativo'}`);},limits:'O recorte pediátrico >5 anos e <48 horas é conservador deste site, não uma contraindicação universal de toda versão publicada. Não usar este perfil em crianças ≤5 anos, reavaliações ou trauma pediátrico ≥48 h, comunicação/exame não confiáveis ou sensibilidade alterada. Fratura exposta, deformidade, comprometimento neurovascular e politrauma exigem abordagem própria. A incapacidade de quatro passos deve ocorrer imediatamente após o trauma E na avaliação; passos independentes mesmo mancando contam como apoio. A marcha normal prévia refere-se a antes da lesão. Não basta somar achados: a zona dolorosa é necessária. Resultado negativo não exclui toda fratura, lesão fisária, tendínea ou sindesmótica e não rastreia todos os ossos do pé. Dor persistente ou piora exige reavaliação. Estudos pediátricos têm desfechos distintos: Plint avaliou fraturas significativas, não toda lesão; a metanálise teve falsos negativos. A série brasileira de 2025 foi retrospectiva e restrita a pacientes radiografados. Não autoriza alta ou tratamento automático.',sources:[ref('Plint et al. · validação pediátrica prospectiva · 1999','https://pubmed.ncbi.nlm.nih.gov/10530658/'),ref('Libetta et al. · aplicação pediátrica · 1999','https://pubmed.ncbi.nlm.nih.gov/10505914/'),ref('Dowling et al. · metanálise pediátrica · 2009','https://pubmed.ncbi.nlm.nih.gov/19187397/'),ref('RCH · entorse de tornozelo em pediatria','https://www.rch.org.au/clinicalguide/guideline_index/fractures/Ankle_Sprains_-_Emergency_Department/'),ref('Carvalho et al. · série retrospectiva brasileira · 2025','https://pmc.ncbi.nlm.nih.gov/articles/PMC11879485/'),ref('NSW Health · Ottawa ankle rules · adultos','https://aci.health.nsw.gov.au/ecat/appendices/ottawa-ankle-adult')]}));
clinicalScores.push(rule({id:'canadian-cspine',name:'Canadian C-Spine Rule',specialty:'Trauma',population:'≥16 anos · alerta e estável',subtitle:'Regra sequencial para avaliação cervical',scope:'Trauma contuso em pessoas ≥16 anos, Glasgow 15 e estabilidade clínica. Primeiro avaliar alto risco; rotação ativa só pode ser examinada se não houver alto risco e existir ao menos um fator de baixo risco.',fields:[y('age','Idade ≥65 anos'),y('mechanism','Mecanismo perigoso',1,'Queda >1 m/5 degraus, carga axial, colisão em alta velocidade, capotamento/ejeção, veículo recreativo motorizado, bicicleta ou acidente equestre (NICE).'),y('paresthesia','Parestesia em membros'),y('rear','Colisão traseira simples'),y('sitting','Confortável sentado'),y('walk','Deambulou em algum momento após o trauma'),y('midline','Ausência de dor na linha média cervical'),y('delayed','Início tardio da dor cervical'),s('rotation','Rotação ativa de 45° para AMBOS os lados',[[0,'Não examinada por contraindicação / segurança'],[1,'Examinada com segurança: incapaz'],[2,'Examinada com segurança: capaz']],'Não realizar se houver alto risco ou nenhum fator de baixo risco.')],formula:'Alto risco → imagem; sem alto risco mas sem baixo risco → imagem; elegível para rotação e incapaz → imagem. Capaz, em avaliação segura, permite considerar liberação.',compute:x=>{const high=x.age||x.mechanism||x.paresthesia,low=x.rear||x.sitting||x.walk||x.midline||x.delayed;if(!high&&low&&x.rotation===0)return {...ruleResult(true,'Regra incompleta: rotação não avaliada','Não liberar coluna com avaliação incompleta. Definir avaliação segura ou imagem pelo protocolo.','Sem alto risco; com baixo risco; rotação desconhecida'),displayValue:'Incompleta'};const pos=!!(high||!low||x.rotation!==2);const r=ruleResult(pos,pos?'Regra indica investigação por imagem':'Critérios de baixo risco e rotação preservada','Integrar à avaliação clínica e protocolo de coluna. Não forçar movimento nem desconsiderar déficit neurológico.',`Alto risco=${!!high}; baixo risco=${!!low}; rotação=${x.rotation===2?'preservada':x.rotation===1?'limitada':'não examinada'}`);if((high||!low)&&x.rotation!==0)r.alerts=['Rotação foi informada fora do ramo seguro da regra. Esse resultado não autoriza mobilização; prevalece a indicação de investigação.'];return r;},limits:'Colisão traseira simples não inclui capotamento, impacto de veículo grande, alta velocidade ou ser projetado ao tráfego. Não aplicar em GCS <15, instabilidade ou crianças <16 anos.',sources:[ref('NICE NG41 · Canadian C-spine rule e imagem','https://www.nice.org.uk/guidance/NG41/chapter/recommendations')]}));
clinicalScores.push(rule({id:'ottawa-sah',name:'Ottawa · HSA',specialty:'Neurologia',population:'≥16 anos · alerta, sem déficit focal',subtitle:'Investigação de hemorragia subaracnóidea',scope:'Cefaleia nova, intensa e não traumática, com pico em até 1 h; paciente alerta, ≥16 anos, sem déficit focal. Não aplicar a história de aneurisma/HSA/tumor cerebral, papiledema ou ≥3 episódios semelhantes em 6 meses; apresentação em até 14 dias.',fields:[y('age','Idade ≥40 anos'),y('neck','Dor ou rigidez cervical'),y('loc','Perda de consciência testemunhada'),y('exertion','Início durante esforço'),y('thunder','Cefaleia em trovoada: pico instantâneo'),y('flex','Flexão cervical limitada ao exame')],formula:'Qualquer um dos seis achados torna a regra positiva para investigação de HSA.',compute:x=>{const c=Object.values(x).reduce((a,b)=>a+b,0);return ruleResult(c>0,c?'Necessita investigação de HSA pela regra':'Nenhum critério presente na população elegível','Cefaleia súbita exige avaliação urgente. Escolher investigação conforme tempo de início, exame e protocolo; a regra não define sozinha TC, punção ou angiografia.',`${c} critério(s) presente(s)`);},limits:'Alta sensibilidade com baixa especificidade nas coortes; positiva não diagnostica HSA. Negativa não exclui outras causas graves e só tem significado se todos os critérios de aplicação forem atendidos.',sources:[pmc('PMC5687926','Perry et al. · validação multicêntrica Ottawa SAH · 2017'),pmc('PMC5698031','Autores da regra · resumo dos seis critérios Ottawa SAH')]}));
for(const small of [true,false]) clinicalScores.push(rule({id:small?'pecarn-under2':'pecarn-over2',name:small?'PECARN · TCE <2 anos':'PECARN · TCE 2–17 anos',specialty:'Pediatria',population:small?'Crianças <2 anos':'Crianças e adolescentes de 2–17 anos',subtitle:'Regra de risco muito baixo de lesão cerebral importante',scope:'Trauma craniano contuso, nas primeiras 24 h, Glasgow 14–15. Exige avaliação pediátrica e aplicação na faixa etária indicada. Não aplicar em trauma penetrante, suspeita de abuso, distúrbios hemorrágicos ou exame não confiável. Crianças com derivação ventricular (shunt ventriculoperitoneal ou ventriculoatrial) ou tumor cerebral conhecido ficaram fora da derivação principal de 2009 e da validação de 2024. Nessas condições, não presumir validação da classificação de risco muito baixo; realizar avaliação individualizada conforme protocolo.',fields:[y('mental','Glasgow 14 OU estado mental alterado',1,'Agitação, sonolência, perguntas repetidas ou resposta lenta à comunicação.'),y('fracture',small?'Fratura de crânio palpável':'Sinais de fratura de base do crânio'),...(small?[y('hematoma','Hematoma de couro cabeludo não frontal'),y('loc','Perda de consciência ≥5 segundos'),y('behavior','Não age normalmente segundo responsáveis')]:[y('loc','Qualquer perda de consciência'),y('vomit','Vômitos'),y('headache','Cefaleia intensa')]),y('mechanism','Mecanismo grave',1,`Colisão com ejeção, morte de outro ocupante ou capotamento; pedestre/ciclista sem capacete atingido por veículo motorizado; objeto de alto impacto; queda >${small?'0,9':'1,5'} m.`)],formula:'Todos os seis achados ausentes → critérios de risco muito baixo atendidos. Qualquer achado presente → fora desse grupo; não equivale a TC obrigatória para todos.',compute:x=>{const c=Object.values(x).reduce((a,b)=>a+b,0);const r=ruleResult(c>0,c?'Fora do grupo de risco muito baixo':'Critérios de risco muito baixo atendidos','Definir observação e/ou imagem conforme exame, evolução, combinação dos achados e protocolo. Orientações e supervisão adequadas são necessárias para qualquer alta.',`${c} achado(s) presente(s); faixa ${small?'<2':'2–17'} anos`);if(x.mental||x.fracture){r.label='Achado de maior risco: alteração mental ou fratura';r.action='Avaliação imediata por equipe pediátrica/trauma e consideração de TC conforme protocolo.';}return r;},limits:'Não é soma de pontos para estimar probabilidade individual. Atenção especial a lactentes <3 meses. Glasgow 14 não é normalidade: verificar alteração mental. Não usar para excluir concussão ou substituir avaliação de maus-tratos.',sources:[ref('CHOP · Head Trauma Clinical Pathway · revisão julho 2026','https://www.chop.edu/clinical-pathway/head-trauma-acute-clinical-pathway'),ref('Kuppermann et al. · PECARN original · Lancet 2009 · PMID 19758692','https://pubmed.ncbi.nlm.nih.gov/19758692/'),ref('Holmes et al. · PECARN validação prospectiva · Lancet Child Adolesc Health 2024 · PMID 38609287','https://pubmed.ncbi.nlm.nih.gov/38609287/')]}));
clinicalScores.push(make({id:'iss',name:'ISS',specialty:'Trauma',subtitle:'Gravidade anatômica por regiões corporais',max:75,scope:'Trauma com lesões já codificadas por profissional treinado em AIS, usando a mesma edição. Inserir o maior AIS em cada uma das seis regiões ISS; 0 representa ausência de lesão codificada.',fields:[['head','Cabeça/pescoço'],['face','Face'],['chest','Tórax'],['abdomen','Abdome/conteúdo pélvico'],['limbs','Extremidades/cintura pélvica'],['external','Superfície externa']].map(([id,label])=>meta(n(id,`Maior AIS · ${label}`,0,6))),formula:'Soma dos quadrados dos três maiores AIS de regiões diferentes. Qualquer AIS 6 fixa ISS em 75.',compute:x=>{const v=Object.values(x).sort((a,b)=>b-a),top=v.slice(0,3),total=v.includes(6)?75:top.reduce((a,b)=>a+b*b,0);return result(total,'Gravidade anatômica pelo ISS','Registrar as lesões e a edição AIS. Maior valor indica maior gravidade anatômica; não implica prognóstico individual definitivo.',v.includes(6)?'AIS 6 presente → ISS fixado em 75':top.map(a=>`${a}²`).join(' + '));},limits:'Não atribui AIS a partir de descrições de lesão. Exige codificação adequada/licença quando aplicável. Lesões múltiplas na mesma região não ocupam mais de uma parcela; esta é a diferença para NISS.',sources:[pmc('PMC6755696','Estudo de gravidade no trauma · definição do ISS tradicional e regra AIS 6')]}));
clinicalScores.push(make({id:'scorten',name:'SCORTEN',specialty:'Dermatologia',subtitle:'Gravidade na necrólise epidérmica',max:7,scope:'Adultos com síndrome de Stevens–Johnson/necrólise epidérmica tóxica. Avaliação inicial e reavaliação conforme protocolo especializado; manter componentes do mesmo período.',fields:[y('age','Idade >40 anos'),y('cancer','Neoplasia maligna'),y('hr','FC >120 bpm'),y('bsa','Descolamento epidérmico >10% da superfície corporal'),y('urea','Ureia >10 mmol/L',1,'Equivale aproximadamente a ureia >60 mg/dL ou BUN >28 mg/dL. NÃO confundir ureia com BUN.'),y('glucose','Glicemia >14 mmol/L',1,'Aproximadamente >252 mg/dL.'),y('hco','Bicarbonato <20 mmol/L')],action:'Maior escore indica maior gravidade na população estudada. SJS/NET exige avaliação especializada urgente, identificação do agente e suporte apropriado.',limits:'Não diagnostica SJS/NET nem determina terapia ou limitação de suporte. Não apresentamos probabilidades históricas como previsão individual atual. Conferir especialmente as unidades de ureia e BUN.',sources:[ref('Bastuji-Garin et al. · SCORTEN original · 2000 · PMID 10951229','https://pubmed.ncbi.nlm.nih.gov/10951229/'),ref('British Association of Dermatologists · diretriz SJS/NET','https://onlinelibrary.wiley.com/doi/10.1111/bjd.14530')]}));
